sys_script_include.script:
var WF_ProblemWorkSpaceUtil = Class.create();
WF_ProblemWorkSpaceUtil.prototype = Object.extendsObject(AbstractAjaxProcessor, {
	verifyAccess: function(problem) {

        if ((problem.major_problem.toString() === "false" && (gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner') || gs.getUser().isMemberOf(problem.assignment_group))) || (problem.major_problem.toString() === "true" && ((gs.hasRole('problem_manager') || gs.hasRole('x_g_wfb_inc_mgmt.wf_incprb_process_owner'))))) {
            return true;

        } else {
            return false;
        }
    },
    type: 'WF_ProblemWorkSpaceUtil'
});
